  // Generic caller-defined button from the `reply` tool's `buttons` param.
  // Security mirrors the perm: path and the text-reply path: allowFrom
  // must contain the sender.
  const access = loadAccess()
  const senderId = String(ctx.from.id)
  if (!access.allowFrom.includes(senderId)) {
    await ctx.answerCallbackQuery({ text: 'Not authorized.' }).catch(() => {})
    return
  }
  const msg = ctx.callbackQuery.message
  // The tap only carries callback_data — recover the visible label from the
  // keyboard that was actually sent, so the injected inbound text reads
  // exactly like the user typed the button's label.
  let label = data
  const kb = msg && 'reply_markup' in msg ? msg.reply_markup?.inline_keyboard : undefined
  if (kb) {
    for (const row of kb) {
      const hit = row.find(b => 'callback_data' in b && b.callback_data === data)
      if (hit) { label = hit.text; break }
    }
  }
  await ctx.answerCallbackQuery({ text: label }).catch(() => {})
  // Strip the keyboard and show the outcome so the same tap can't fire twice.
  if (msg && 'text' in msg && msg.text) {
    await ctx.editMessageText(`${msg.text}\n\n${label} ✅`).catch(() => {})
  }
  mcp.notification({
    method: 'notifications/claude/channel',
    params: {
      content: label,
      meta: {
        chat_id: String(ctx.chat!.id),
        ...(msg ? { message_id: String(msg.message_id) } : {}),
        user: ctx.from.username ?? senderId,
        user_id: senderId,
        ts: new Date().toISOString(),
        button_data: data,
      },
    },
  }).catch(err => {
    process.stderr.write(`telegram channel: failed to deliver button tap: ${err}\n`)
  })
  return
}
